{
  "packet_id": "H6-T01-2",
  "claim_id": "C062",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C062.component",
    "value": "Relabelling availability alone must not count as improvement.",
    "scope": "Validity of improvement claims; the limitation concerns relabelling by itself.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P032 explicitly excludes availability relabelling alone from counting as improvement."
    }
  },
  "signal_basis": {
    "component_id": "C062.signal_basis",
    "value": "Reduction tests hold the agreed start deadline fixed and observe whether actual lateness persists. Improvement assessment tracks late-start frequency and minutes against existing-service deadlines.",
    "scope": "Observed turnaround performance under fixed service deadlines, including the reproducing reduced configuration and subsequent trial assessment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish fixed deadlines, the repeated lateness signal, and performance measures tied to existing-service deadlines."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C062.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a measurement limitation without an unresolved empirical relation."
    }
  },
  "rationale": "Changing an availability label alone does not improve actual start times against unchanged service deadlines. It may change how bookings are classified, but the mapping's performance measures license excluding that change alone as improvement.",
  "uncertainty": "This judgment does not address availability changes accompanied by operational changes that affect actual starts.",
  "anomalies": []
}
